export const FAQS = [
  {
    q: "Where does the metal come from?",
    a: "Every gram is reclaimed — old jewelry, industrial offcuts and coin scrap, refined and recast in our workshop. We haven't ordered newly mined gold since 2019.",
  },
  {
    q: "Can a ring be resized later?",
    a: "Yes, for the life of the piece. First resize is free within a year of purchase; after that it's a flat workshop fee, wherever you are.",
  },
  {
    q: "How long does an order take?",
    a: "In-stock pieces ship within 3 business days. Made-to-order and resized pieces take 2–3 weeks, since each one is carved and cast individually.",
  },
  {
    q: "What if a stone loosens or a clasp fails?",
    a: "Every piece carries a lifetime repair promise — send it back and we'll reset, resolder or rebuild it at no cost, indefinitely.",
  },
  {
    q: "Do you ship internationally?",
    a: "We ship to most countries with insured, tracked delivery. Duties are calculated at checkout so there are no surprises at your door.",
  },
];
